[CmdletBinding()]
param([ValidateSet('provision','migrate','status','import','timeline-import','timeline-status','timeline-export','backup','restore')][string]$Command='status',[string]$BackupFile,[string]$ConfirmDatabase)
Set-StrictMode -Version Latest
$ErrorActionPreference='Stop'
$root=[IO.Path]::GetFullPath((Join-Path $PSScriptRoot '..'))
. (Join-Path $PSScriptRoot 'demi-db-auth.ps1')
$config=Get-Content -Raw -LiteralPath (Join-Path $root 'config\database.json') -Encoding UTF8|ConvertFrom-Json
foreach($name in @('database','adminUser','ownerRole','applicationUser','schema')){if("$($config.$name)"-notmatch'^[a-z][a-z0-9_]{0,62}$'){throw "Unsafe database configuration value: $name"}}
$psqlCommand=Get-Command psql.exe -ErrorAction SilentlyContinue|Select-Object -First 1
$bin=if($psqlCommand){Split-Path -Parent $psqlCommand.Source}else{Get-ChildItem 'C:\Program Files\PostgreSQL\*\bin' -Directory -ErrorAction SilentlyContinue|Sort-Object FullName -Descending|Select-Object -ExpandProperty FullName -First 1}
if(-not$bin){throw 'PostgreSQL command-line tools were not found. File-only Demi remains available.'}
$psql=Join-Path $bin 'psql.exe';$pgDump=Join-Path $bin 'pg_dump.exe';$pgRestore=Join-Path $bin 'pg_restore.exe'
foreach($tool in @($psql,$pgDump,$pgRestore)){if(-not(Test-Path -LiteralPath $tool -PathType Leaf)){throw "PostgreSQL tool not found: $tool"}}
$localRoot=Join-Path $env:LOCALAPPDATA 'Demiurge';$backupRoot=Join-Path $localRoot 'database-backups';[void][IO.Directory]::CreateDirectory($localRoot)
function Invoke-Psql([string]$Database,[string]$User,[string[]]$Extra,[string]$Password){$old=$env:PGPASSWORD;try{if($Password){$env:PGPASSWORD=$Password}else{Remove-Item Env:PGPASSWORD -ErrorAction SilentlyContinue};$out=&$psql -X -v ON_ERROR_STOP=1 -h "$($config.host)" -p "$($config.port)" -U $User -d $Database @Extra 2>&1;if($LASTEXITCODE-ne0){throw($out-join[Environment]::NewLine)};,$out}finally{if($null-ne$old){$env:PGPASSWORD=$old}else{Remove-Item Env:PGPASSWORD -ErrorAction SilentlyContinue}}}
function Invoke-Migrations{$password=Get-DemiDatabasePassword;$migrationRoot=Join-Path $root 'database\migrations';foreach($file in Get-ChildItem -LiteralPath $migrationRoot -Filter '*.sql' -File|Sort-Object Name){$checksum=(Get-FileHash -LiteralPath $file.FullName -Algorithm SHA256).Hash.ToLowerInvariant();$version=$file.BaseName.Replace("'","''");$tableExists=(Invoke-Psql $config.database $config.adminUser @('-Atc',"SELECT to_regclass('demi.schema_migrations') IS NOT NULL") $null|Select-Object -First 1);$existing=$null;if("$tableExists"-eq't'){$existing=(Invoke-Psql $config.database $config.applicationUser @('-Atc',"SELECT checksum_sha256 FROM demi.schema_migrations WHERE version='$version'") $password|Select-Object -First 1)};if($existing){if("$existing"-ne$checksum){throw "Applied migration $version has changed on disk."};continue};[void](Invoke-Psql $config.database $config.adminUser @('-f',$file.FullName) $null);[void](Invoke-Psql $config.database $config.adminUser @('-c',"INSERT INTO demi.schema_migrations(version,checksum_sha256) VALUES ('$version','$checksum')") $null)}}
switch($Command){
'provision'{$bytes=[byte[]]::new(32);$rng=[Security.Cryptography.RandomNumberGenerator]::Create();try{$rng.GetBytes($bytes)}finally{$rng.Dispose()};$password=[Convert]::ToBase64String($bytes).TrimEnd('=').Replace('+','-').Replace('/','_');$quoted=$password.Replace("'","''");$roles='DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM pg_roles WHERE rolname=''__OWNER__'')THEN CREATE ROLE __OWNER__ NOLOGIN;END IF;IF NOT EXISTS(SELECT 1 FROM pg_roles WHERE rolname=''__APP__'')THEN CREATE ROLE __APP__ LOGIN PASSWORD ''__PASSWORD__'';ELSE ALTER ROLE __APP__ PASSWORD ''__PASSWORD__'';END IF;END $$;';$roles=$roles.Replace('__OWNER__',$config.ownerRole).Replace('__APP__',$config.applicationUser).Replace('__PASSWORD__',$quoted);[void](Invoke-Psql postgres $config.adminUser @('-c',$roles) $null);$exists=Invoke-Psql postgres $config.adminUser @('-Atc',"SELECT 1 FROM pg_database WHERE datname='$($config.database)'") $null;if(-not$exists){[void](Invoke-Psql postgres $config.adminUser @('-c',"CREATE DATABASE $($config.database) OWNER $($config.ownerRole) ENCODING 'UTF8' TEMPLATE template0") $null)};[void](Write-DemiDatabasePassFile -Database $config -Password $password);Invoke-Migrations;"Demi database provisioned at $($config.host):$($config.port)/$($config.database)."}
'migrate'{Invoke-Migrations;'Demi database migrations are current.'}
'status'{$password=Get-DemiDatabasePassword;$result=Invoke-Psql $config.database $config.applicationUser @('-Atc',"SELECT current_database()||'|'||current_user||'|'||(SELECT count(*) FROM demi.schema_migrations)||'|'||(SELECT count(*) FROM demi.silos WHERE kind='global')") $password;$parts=("$($result|Select-Object -First 1)").Split('|');[pscustomobject]@{healthy=$true;database=$parts[0];user=$parts[1];migrations=[int]$parts[2];globalSilos=[int]$parts[3];host="$($config.host):$($config.port)"}|ConvertTo-Json}
'import'{& (Join-Path $PSScriptRoot 'demi-memory-import.ps1') sync -ProjectRoot $root}
'timeline-import'{& (Join-Path $PSScriptRoot 'demi-timeline.ps1') import -ProjectRoot $root}
'timeline-status'{& (Join-Path $PSScriptRoot 'demi-timeline.ps1') status -ProjectRoot $root}
'timeline-export'{& (Join-Path $PSScriptRoot 'demi-timeline.ps1') export -ProjectRoot $root}
'backup'{[void][IO.Directory]::CreateDirectory($backupRoot);$destination=if($BackupFile){[IO.Path]::GetFullPath($BackupFile)}else{Join-Path $backupRoot("demi-{0}.dump"-f[DateTime]::Now.ToString('yyyyMMdd-HHmmss'))};&$pgDump -Fc -h "$($config.host)" -p "$($config.port)" -U $config.adminUser -d $config.database -f $destination;if($LASTEXITCODE-ne0){throw 'PostgreSQL backup failed.'};$destination}
'restore'{if(-not$BackupFile-or-not(Test-Path -LiteralPath $BackupFile -PathType Leaf)){throw 'Restore requires -BackupFile pointing to an existing dump.'};if($ConfirmDatabase-ne$config.database){throw "Restore is destructive. Repeat with -ConfirmDatabase $($config.database)."};&$pgRestore --clean --if-exists --exit-on-error -h "$($config.host)" -p "$($config.port)" -U $config.adminUser -d $config.database $BackupFile;if($LASTEXITCODE-ne0){throw 'PostgreSQL restore failed.'};'Demi database restored. Run migrate and status next.'}
}
